    "eDesc": "Implement function `calculateChannelMargins(mfgCost, mfgMarginPct, distributorMarginPct, retailerMarginPct)` computing vertical value chain price waterfall. Return `{ mfgSellingPrice: number, distributorSellingPrice: number, finalRetailPriceMsp: number, totalChannelMarginPercent: number }`.",
    "eStarter": "/**\n * Computes vertical channel margins and price buildup through manufacturer, distributor, and retailer.\n * \n * @param {number} mfgCost - Manufacturer direct cost per unit\n * @param {number} mfgMarginPct - Manufacturer markup percentage on cost\n * @param {number} distributorMarginPct - Distributor markup percentage on purchase price\n * @param {number} retailerMarginPct - Retailer markup percentage on distributor price\n * @returns {{\n *   mfgSellingPrice: number,\n *   distributorSellingPrice: number,\n *   finalRetailPriceMsp: number,\n *   totalChannelMarginPercent: number\n * }} Multi-tier channel price cascade\n */\nfunction calculateChannelMargins(mfgCost, mfgMarginPct, distributorMarginPct, retailerMarginPct) {\n  // TODO: Build prices sequentially: mfgPrice = cost*(1+mfgMargin); distPrice = mfgPrice*(1+distMargin); retailPrice = distPrice*(1+retailMargin); return report\n  \n}",
    "eHint": "mfgPrice = mfgCost * (1 + mfgMargin / 100); wholesalerPrice = mfgPrice * (1 + wMargin / 100); retailMsp = wholesalerPrice * (1 + rMargin / 100); priceEscalation = retailMsp - mfgCost; return { manufacturerPrice: Number(mfgPrice.toFixed(2)), wholesalerPrice: Number(wholesalerPrice.toFixed(2)), consumerRetailMsp: Number(retailMsp.toFixed(2)), priceEscalation: Number(priceEscalation.toFixed(2)) }.",
    "eTest": "const ch = calculateChannelMargins(100, 20, 15, 25); // Mfg = 120, Wholesaler = 138, Retail = 172.50\nif (ch.manufacturerPrice !== 120.00 || ch.wholesalerPrice !== 138.00 || ch.consumerRetailMsp !== 172.50) throw new Error('Channel margins calculation failed');\nconst directD2c = calculateChannelMargins(100, 50, 0, 0);\nif (directD2c.consumerRetailMsp !== 150.00 || directD2c.wholesalerPrice !== 150.00) throw new Error('Direct D2C zero intermediary check failed');\nconst zeroMargin = calculateChannelMargins(50, 0, 0, 0);\nif (zeroMargin.consumerRetailMsp !== 50.00) throw new Error('Zero margin passthrough failed');",
    "aTitle": "Channel Conflict Resolution & Direct-to-Consumer (D2C) Margin Calculator",
    "aDesc": "Implement function `evaluateD2cTransitionMargin(retailMsp, wholesaleSellingPrice, d2cShippingCostPerUnit)` comparing D2C vs wholesale profit margins. Return `{ d2cNetRealization: number, marginAdvantagePerUnit: number, isD2cMoreProfitable: boolean }`.",
    "aStarter": "/**\n * Compares unit margins between traditional wholesale distribution and Direct-to-Consumer (D2C) channels.\n * \n * @param {number} retailMsp - Final consumer retail price\n * @param {number} wholesaleSellingPrice - Price received from wholesale distributors\n * @param {number} d2cShippingCostPerUnit - Per-unit fulfillment and shipping cost under D2C\n * @returns {{\n *   d2cNetRealization: number,\n *   marginAdvantagePerUnit: number,\n *   isD2cMoreProfitable: boolean\n * }} D2C channel margin comparison\n */\nfunction evaluateD2cTransitionMargin(retailMsp, wholesaleSellingPrice, d2cShippingCostPerUnit) {\n  // TODO: d2cNet = retailMsp - shipping; advantage = d2cNet - wholesale; return { d2cNetRealization, marginAdvantagePerUnit, isD2cMoreProfitable }\n  \n}",
