    "eTest": "const aida = evaluateAidaFunnel(100000, 2000, 200, 20); // CTR = 2.0%, Lead = 10.0%, Sales = 10.0%, Overall = 0.02%\nif (aida.clickThroughRateAttentionToInterest !== 2.00 || aida.leadRateInterestToDesire !== 10.00 || aida.purchaseRateDesireToAction !== 10.00) throw new Error('AIDA conversion failed');\nconst highPerf = evaluateAidaFunnel(10000, 500, 100, 25);\nif (highPerf.purchaseRateDesireToAction !== 25.00) throw new Error('High performance AIDA failed');\nconst zeroSales = evaluateAidaFunnel(1000, 50, 5, 0);\nif (zeroSales.purchaseRateDesireToAction !== 0.00) throw new Error('Zero sales AIDA check failed');",
    "aTitle": "Promotional Mix Budget Allocation Calculator (Omnichannel Distribution, Channel Conflict & Value Chain Margin Decomposition)",
    "aDesc": "Implement function `allocatePromoMixBudget(totalBudget, advertisingPct, digitalMarketingPct, salesPromotionPct, prPct)` computing promotional budget split. Return `{ advertisingAmount: number, digitalAmount: number, salesPromoAmount: number, prAmount: number, isFullyAllocated: boolean }`.",
    "aStarter": "/**\n * Allocates corporate promotional budget across advertising, digital performance, sales promo, and PR.\n * \n * @param {number} totalBudget - Total annual promotional budget\n * @param {number} advertisingPct - % allocation to traditional media ads\n * @param {number} digitalMarketingPct - % allocation to digital search/social\n * @param {number} salesPromotionPct - % allocation to price discounts/trade promos\n * @param {number} prPct - % allocation to public relations and sponsorships\n * @returns {{\n *   advertisingAmount: number,\n *   digitalAmount: number,\n *   salesPromoAmount: number,\n *   prAmount: number,\n *   isFullyAllocated: boolean\n * }} Promotional mix expenditure breakdown\n */\nfunction allocatePromoMixBudget(totalBudget, advertisingPct, digitalMarketingPct, salesPromotionPct, prPct) {\n  // TODO: Multiply totalBudget by each percentage and check if sum equals 100%\n  \n}",
