    "aTest": "const b = allocatePromoMixBudget(100000, 40, 30, 20, 10); // 40k, 30k, 20k, 10k\nif (b.advertisingAmount !== 40000 || b.digitalAmount !== 30000 || !b.isFullyAllocated) throw new Error('Promo mix budget allocation failed');"
