    "eTitle": "SERVQUAL 5-Dimension Service Quality Gap Engine",
    "eDesc": "Implement function `calculateServqualGaps(tangiblesScores, reliabilityScores, responsivenessScores, assuranceScores, empathyScores)` computing Parasuraman's Gap 5 across 5 dimensions. Return `{ tangiblesGap: number, reliabilityGap: number, responsivenessGap: number, assuranceGap: number, empathyGap: number, compositeServqualScore: number, serviceQualityTier: 'EXCEEDS_SERVICE_EXPECTATIONS' | 'SERVICE_DEFICIT_DETECTED' }`.",
    "eStarter": "/**\n * Computes SERVQUAL 5-dimension service quality gaps (Perception - Expectation).\n * \n * @param {{ p: number, e: number }} tangiblesScores - Physical facilities and appearance scores\n * @param {{ p: number, e: number }} reliabilityScores - Accurate, dependable service scores\n * @param {{ p: number, e: number }} responsivenessScores - Prompt, helpful service scores\n * @param {{ p: number, e: number }} assuranceScores - Trust, courtesy, and security scores\n * @param {{ p: number, e: number }} empathyScores - Caring, individualized attention scores\n * @returns {{\n *   tangiblesGap: number,\n *   reliabilityGap: number,\n *   responsivenessGap: number,\n *   assuranceGap: number,\n *   empathyGap: number,\n *   compositeServqualScore: number,\n *   serviceQualityTier: 'EXCEEDS_SERVICE_EXPECTATIONS' | 'SERVICE_DEFICIT_DETECTED'\n * }} Comprehensive SERVQUAL diagnostic report\n */\nfunction calculateServqualGaps(tangiblesScores, reliabilityScores, responsivenessScores, assuranceScores, empathyScores) {\n  // TODO: Compute gap = p - e for each dimension; avgGap = sum(gaps) / 5; return report\n  \n}",
    "eHint": "For each dim compute gap = dim.perception - dim.expectation; avgGap = sum(gaps) / 5; return { tangiblesGap: tan.p - tan.e, reliabilityGap: rel.p - rel.e, responsivenessGap: resp.p - resp.e, assuranceGap: ass.p - ass.e, empathyGap: emp.p - emp.e, compositeServqualScore: Number(avgGap.toFixed(2)), serviceQualityTier: avgGap >= 0 ? 'EXCEEDS_SERVICE_EXPECTATIONS' : 'SERVICE_DEFICIT_DETECTED' }.",
    "eTest": "const s = calculateServqualGaps({ p: 6, e: 5 }, { p: 7, e: 6 }, { p: 6, e: 5 }, { p: 7, e: 6 }, { p: 6, e: 5 }); // All +1 -> Avg +1.00\nif (s.compositeServqualScore !== 1.00 || s.serviceQualityTier !== 'EXCEEDS_SERVICE_EXPECTATIONS') throw new Error('Positive SERVQUAL failed');\nconst deficit = calculateServqualGaps({ p: 4, e: 6 }, { p: 3, e: 6 }, { p: 4, e: 6 }, { p: 5, e: 6 }, { p: 4, e: 6 }); // All negative\nif (deficit.compositeServqualScore >= 0 || deficit.serviceQualityTier !== 'SERVICE_DEFICIT_DETECTED') throw new Error('Deficit SERVQUAL failed');\nconst zeroGap = calculateServqualGaps({ p: 5, e: 5 }, { p: 5, e: 5 }, { p: 5, e: 5 }, { p: 5, e: 5 }, { p: 5, e: 5 });\nif (zeroGap.compositeServqualScore !== 0.00) throw new Error('Parity SERVQUAL check failed');",
