    "eTitle": "Decision Making Unit (DMU) Influence & Buying Center Engine",
    "eDesc": "Implement function `evaluateB2bBuyingCenter(initiatorVote, influencerVote, gatekeeperVote, deciderVote, buyerVote, userVote)` modeling B2B Decision Making Unit (DMU) consensus. Return `{ consensusScore: number, isProcurementApproved: boolean, gatingReason: 'DEAL_APPROVED' | 'DECIDER_VETO' | 'INSUFFICIENT_CONSENSUS' }`.",
    "eStarter": "/**\n * Evaluates consensus across the 6 stakeholders of an enterprise B2B Decision Making Unit (DMU).\n * \n * @param {number} initiatorVote - Initiator approval rating (1-10)\n * @param {number} influencerVote - Technical influencer rating (1-10)\n * @param {number} gatekeeperVote - Procurement gatekeeper rating (1-10)\n * @param {number} deciderVote - Executive decider rating (1-10)\n * @param {number} buyerVote - Contract buyer rating (1-10)\n * @param {number} userVote - End-user department rating (1-10)\n * @returns {{\n *   consensusScore: number,\n *   isProcurementApproved: boolean,\n *   gatingReason: 'DEAL_APPROVED' | 'DECIDER_VETO' | 'INSUFFICIENT_CONSENSUS'\n * }} B2B procurement decision model\n */\nfunction evaluateB2bBuyingCenter(initiatorVote, influencerVote, gatekeeperVote, deciderVote, buyerVote, userVote) {\n  // TODO: Compute weighted score; check decider >= 7 and weighted >= 7.0; return report\n  \n}",
