    "eDesc": "Implement function `evaluateDecoyPricingEffect(optionAPrice, optionADemand, optionBPrice, optionBDemand, decoyPrice, decoyDemandShiftPct)` computing baselineRevenue, newRevenueWithDecoy, revenueLift, and percentageLift under Asymmetric Dominance (Decoy Effect). Return `{ baselineRevenue: number, newRevenueWithDecoy: number, revenueLift: number, percentageLift: number }`.",
    "eStarter": "/**\n * Models revenue impact of Asymmetric Dominance (Decoy Effect) shifting customer demand from option A to target premium option B.\n * \n * @param {number} optionAPrice - Basic tier price\n * @param {number} optionADemand - Initial units sold of basic option A\n * @param {number} optionBPrice - Target premium tier price\n * @param {number} optionBDemand - Initial units sold of target premium option B\n * @param {number} decoyPrice - Asymmetrically dominated decoy price\n * @param {number} decoyDemandShiftPct - % of option A buyers redirected to premium option B\n * @returns {{\n *   baselineRevenue: number,\n *   newRevenueWithDecoy: number,\n *   revenueLift: number,\n *   percentageLift: number\n * }} Decoy pricing revenue lift metrics\n */\nfunction evaluateDecoyPricingEffect(optionAPrice, optionADemand, optionBPrice, optionBDemand, decoyPrice, decoyDemandShiftPct) {\n  // TODO: baseRev = priceA*qa + priceB*qb; shiftedUnits = qa * (shiftPct/100); newQA = qa - shiftedUnits; newQB = qb + shiftedUnits;\n  // newRev = priceA*newQA + priceB*newQB; revLift = newRev - baseRev; return report\n  \n}",
    "eHint": "baseRev = optionAPrice * optionADemand + optionBPrice * optionBDemand; shiftedUnits = optionADemand * (decoyDemandShiftPct / 100); newQA = optionADemand - shiftedUnits; newQB = optionBDemand + shiftedUnits; newRev = optionAPrice * newQA + optionBPrice * newQB; revLift = newRev - baseRev; return { baselineRevenue: baseRev, newRevenueWithDecoy: newRev, revenueLift: Number(revLift.toFixed(2)), percentageLift: Number(((revLift / baseRev) * 100).toFixed(2)) }.",
    "eTest": "const res = evaluateDecoyPricingEffect(50, 100, 100, 50, 95, 40); // Base = 5k + 5k = 10k. Shift 40 units from A to B: A=60 ($3k), B=90 ($9k) -> New = 12k (+2k / +20%)\nif (res.baselineRevenue !== 10000 || res.newRevenueWithDecoy !== 12000 || res.revenueLift !== 2000.00 || res.percentageLift !== 20.00) throw new Error('Decoy effect revenue lift failed');\nconst zeroShift = evaluateDecoyPricingEffect(50, 100, 100, 50, 95, 0);\nif (zeroShift.revenueLift !== 0.00) throw new Error('Zero shift decoy check failed');\nconst fullShift = evaluateDecoyPricingEffect(50, 100, 100, 50, 95, 100);\nif (fullShift.newRevenueWithDecoy !== 15000) throw new Error('Full shift decoy check failed');",
    "aTitle": "Price Anchoring Perceived Discount Utility Calculator",
    "aDesc": "Implement function `calculateAnchoringUtility(anchorPrice, salePrice, unitCost)` computing perceived discount and merchant profit margin under price anchoring. Return `{ perceivedSavingsAmount: number, perceivedDiscountPercent: number, merchantProfitMargin: number, isProfitableSale: boolean }`.",
    "aStarter": "/**\n * Models consumer perceived value savings and merchant profitability under price anchoring.\n * \n * @param {number} anchorPrice - Original strikethrough reference price\n * @param {number} salePrice - Actual selling price\n * @param {number} unitCost - Merchant unit product acquisition cost\n * @returns {{\n *   perceivedSavingsAmount: number,\n *   perceivedDiscountPercent: number,\n *   merchantProfitMargin: number,\n *   isProfitableSale: boolean\n * }} Anchoring utility and merchant margin report\n */\nfunction calculateAnchoringUtility(anchorPrice, salePrice, unitCost) {\n  // TODO: savings = anchor - sale; discountPct = (savings / anchor) * 100; profit = sale - cost; return report\n  \n}",
    "aHint": "perceivedSavings = anchorPrice - salePrice; discountPct = (perceivedSavings / anchorPrice) * 100; merchantProfit = salePrice - cost; return { perceivedSavingsAmount: perceivedSavings, perceivedDiscountPercent: Number(discountPct.toFixed(2)), merchantProfitMargin: merchantProfit, isProfitableSale: merchantProfit > 0 }.",
    "aTest": "const a = calculateAnchoringUtility(200, 120, 50); // Savings = $80 (40%), Profit = $70\nif (a.perceivedSavingsAmount !== 80 || a.perceivedDiscountPercent !== 40.00 || a.merchantProfitMargin !== 70) throw new Error('Anchoring utility calculation failed');"
