    "eStarter": "/**\n * Classifies multinational corporate orientation under the EPRG (Ethno, Poly, Regio, Geo) framework.\n * \n * @param {number} ethnocentricPct - Home-country bias percentage\n * @param {number} polycentricPct - Host-country local responsiveness percentage\n * @param {number} regiocentricPct - Regional market standardization percentage\n * @param {number} geocentricPct - Global integration and synthesis percentage\n * @returns {{\n *   dominantOrientation: 'ETHNOCENTRIC' | 'POLYCENTRIC' | 'REGIOCENTRIC' | 'GEOCENTRIC',\n *   glocalizationIndex: number,\n *   globalStrategyType: 'TRUE_GLOCAL_INTEGRATED_NETWORK' | 'MULTIDOMESTIC_DECENTRALIZED' | 'STANDARDIZED_CENTRALIZED_HOME_BASE'\n * }} EPRG global strategy classification\n */\nfunction evaluateEprgOrientation(ethnocentricPct, polycentricPct, regiocentricPct, geocentricPct) {\n  // TODO: Identify dominant orientation; glocalizationIndex = (geo + poly) / 2; return report\n  \n}",
    "eHint": "scores = { ETHNOCENTRIC: ethno, POLYCENTRIC: poly, REGIOCENTRIC: regio, GEOCENTRIC: geo }; dominant = Object.keys(scores).reduce((a, b) => scores[a] > scores[b] ? a : b); return { dominantOrientation: dominant, glocalizationIndex: Number(((geo + poly) / 2).toFixed(2)), globalStrategyType: dominant === 'GEOCENTRIC' ? 'TRUE_GLOCAL_INTEGRATED_NETWORK' : (dominant === 'POLYCENTRIC' ? 'MULTIDOMESTIC_DECENTRALIZED' : 'STANDARDIZED_CENTRALIZED_HOME_BASE') }.",
